int load_segment_descriptor(struct x86_emulate_ctxt *ctxt, u16 selector, int seg, u8 cpl, bool in_task_switch, struct desc_struct *desc) {
    u16 ti, rpl;
    struct desc_struct *table;
    int offset;
    int size;
    int type;

    ti = (selector >> 2) & 1;
    rpl = selector & 3;

    if (!selector && seg != VMC_CS) {
        ctxt->src2.val = 0;
        return real_mode_load_seg(ctxt, seg, selector, desc);
    }

    if (ti) {
        if (ctxt->mode != X86EMUL_MODE_PROT) {
            return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
        }
        table = (struct desc_struct *)ctxt->ldt.base;
        offset = (selector & 0xfffc);
        size = ctxt->ldt.limit;
    } else {
        if (seg == CS) {
            table = (struct desc_struct *)ctxt->gdt.base;
            offset = ctxt->cs.selector;
        } else if (seg == SS) {
            table = (struct desc_struct *)ctxt->gdt.base;
            offset = ctxt->ss.selector;
        } else {
            table = (struct desc_struct *)ctxt->gdt.base;
            offset = (selector & 0xfffc);
            size = ctxt->gdt.limit;
        }
    }

    if (offset > size) {
        return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
    }

    *desc = *(struct desc_struct *)((char *)table + offset);

    type = (*desc).type;

    if ((type & 0x18) != 0x10) {
        return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
    }

    if ((type & 0x18) == 0x10 && (seg == CS || seg == SS)) {
        if ((desc->dpl < rpl) || (desc->dpl < cpl)) {
            return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
        }
    }

    if (seg == CS) {
        if (!(desc->s)) {
            return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
        }
    }

    if (seg == TR) {
        if ((desc->type & 0x1f) != 0x01) {
            return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
        }
    }

    if (seg == LDTR) {
        if ((desc->type & 0x1f) != 0x02) {
            return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
        }
    }

    if (seg == GDT) {
        if ((desc->type & 0x1f) != 0x04) {
            return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
        }
    }

    if (seg == IDT) {
        if ((desc->type & 0x1f) != 0x06) {
            return X86EMUL_EXCEPTION(GP_EXCEPTION, 0);
        }
    }

    if (seg == CS) {
        desc->ti = ti;
        desc->rpl = rpl;
    }

    ctxt->segment[seg] = *desc;

    return X86EMUL_CONTINUE;
}

int load_segment_descriptor(struct x86_emulate_ctxt *ctxt, u16 selector, int seg, u8 cpl, bool in_task_switch, struct desc_struct *desc) {
    struct desc_struct d;
    u16 ti, index;
    int r;

    ti = (selector >> 2) & 1;
    index = selector & ~3;

    if (!index && !ti && ctxt->mode == X86EMUL_MODE_PROT) {
        ctxt->exception = EXC_GP;
        return X86EMUL_EXCEPTION;
    }

    r = read_segment_descriptor(ctxt, ti, index, &d);
    if (r != X86EMUL_CONTINUE)
        return r;

    if ((d.type & 0x18) == 0x10) { /* TI or data segment */
        if ((d.type & 0x04) && (cpl > (d.dpl & 0x03))) {
            ctxt->exception = EXC_GP;
            return X86EMUL_EXCEPTION;
        }
    } else {
        if ((d.type & 0x04) && (cpl > (d.dpl & 0x03))) {
            ctxt->exception = EXC_GP;
            return X86EMUL_EXCEPTION;
        }
    }

    if ((d.type & 0x1f) == 0x05) {
        ctxt->exception = EXC_GP;
        return X86EMUL_EXCEPTION;
    }

    if (seg == VCPU_SREG_CS) {
        if ((d.type & 0x1f) != 0x0b && (d.type & 0x1f) != 0x03) {
            ctxt->exception = EXC_GP;
            return X86EMUL_EXCEPTION;
        }
    } else if (seg == VCPU_SREG_SS) {
        if ((d.type & 0x1f) != 0x09 && (d.type & 0x1f) != 0x01) {
            ctxt->exception = EXC_GP;
            return X86EMUL_EXCEPTION;
        }
    }

    if (desc)
        *desc = d;

    write_segment_register(ctxt, seg, selector, &d);

    return X86EMUL_CONTINUE;
}

int load_segment_descriptor(struct x86_emulate_ctxt *ctxt, u16 selector, int seg, u8 cpl, bool in_task_switch, struct desc_struct *desc) {
    struct desc_struct descriptor;
    int dpl;
    int rpl = SELECTOR_RPL(selector);
    int ti = SELECTOR_TI(selector);
    int index = SELECTOR_INDEX(selector);

    if (!index && !ti && ctxt->mode == X86EMUL_MODE_PROT) {
        /* Null selector in protected mode */
        if (seg == VMENTER_CSD) {
            ctxt->src->error = X86EMUL_EXCEPTION(13); /* General protection */
            return X86EMUL_EXCEPTION;
        }
        descriptor = (struct desc_struct){0};
    } else {
        if (ctxt->mode == X86EMUL_MODE_PROT) {
            if (!ctxt->ops->read_segment_descriptor(ctxt, selector, &descriptor, ti, index)) {
                ctxt->src->error = X86EMUL_EXCEPTION(13); /* General protection */
                return X86EMUL_EXCEPTION;
            }
        } else if (ctxt->mode == X86EMUL_MODE_REAL || ctxt->mode == X86EMUL_MODE_VM86) {
            u32 base = ((selector & 0xFFFC) << 4);
            descriptor = (struct desc_struct){
                .limit = 0xffff,
                .base = base,
                .type = 0x9,
                .s = 1,
                .dpl = 0,
                .p = 1,
                .avl = 0,
                .l = 0,
                .db = 1,
                .granularity = 1
            };
        } else {
            ctxt->src->error = X86EMUL_EXCEPTION(13);
            return X86EMUL_EXCEPTION;
        }
    }

    if (seg == VMENTER_CSD || seg == VMENTER_SSD) {
        if ((descriptor.type & 0x18) != 0x18) {
            ctxt->src->error = X86EMUL_EXCEPTION(13);
            return X86EMUL_EXCEPTION;
        }

        dpl = descriptor.dpl;
        if (cpl > dpl || rpl > dpl) {
            ctxt->src->error = X86EMUL_EXCEPTION(13);
            return X86EMUL_EXCEPTION;
        }

        if (seg == VMENTER_CSD && !in_task_switch && (descriptor.type & 0x10) != 0x10) {
            ctxt->src->error = X86EMUL_EXCEPTION(13);
            return X86EMUL_EXCEPTION;
        }

        if (seg == VMENTER_SSD) {
            if ((descriptor.type & 0x10) != 0x08) {
                ctxt->src->error = X86EMUL_EXCEPTION(13);
                return X86EMUL_EXCEPTION;
            }

            if (cpl != dpl || cpl != rpl) {
                ctxt->src->error = X86EMUL_EXCEPTION(13);
                return X86EMUL_EXCEPTION;
            }
        }
    } else {
        if ((descriptor.type & 0x18) == 0x00) {
            ctxt->src->error = X86EMUL_EXCEPTION(13);
            return X86EMUL_EXCEPTION;
        }

        if ((descriptor.type & 0x18) == 0x10) {
            if (seg == VMENTER_TR) {
                if (rpl != 0 || cpl != 0 || descriptor.dpl != 0) {
                    ctxt->src->error = X86EMUL_EXCEPTION(13);
                    return X86EMUL_EXCEPTION;
                }
            } else {
                ctxt->src->error = X86EMUL_EXCEPTION(13);
                return X86EMUL_EXCEPTION;
            }
        }
    }

    if (desc)
        *desc = descriptor;

    ctxt->regs[seg] = (u16)selector;
    ctxt->seg_desc[seg] = descriptor;

    return X86EMUL_CONTINUE;
}

int load_segment_descriptor(struct x86_emulate_ctxt *ctxt, u16 selector, int seg, u8 cpl, bool in_task_switch, struct desc_struct *desc) {
    struct desc_struct *d;
    int r = X86EMUL_CONTINUE;

    if ((selector & 0xfffc) == 0) {
        /* NULL selector */
        d = NULL;
    } else {
        int s = selector & 0x000f;
        unsigned long selector_base = 0;
        unsigned long selector_limit = 0;
        u32 type;

        if (ctxt->mode == X86EMUL_MODE_REAL) {
            selector_base = selector << 4;
            selector_limit = 0xffff;
        } else if (ctxt->mode == X86EMUL_MODE_VM86) {
            selector_base = selector << 4;
            selector_limit = 0xffff;
        } else {
            unsigned long index = selector >> 3;
            unsigned long ti = (selector >> 2) & 1;
            unsigned long rpl = selector & 0x0003;

            if ((index >= 0x18) && (seg != SEG_CS)) {
                return real_mode(ctxt) ? X86EMUL_CONTINUE : X86EMUL_EXCEPTION;
            }

            if (in_task_switch) {
                if (seg == SEG_SS) {
                    return X86EMUL_EXCEPTION;
                }
                if ((seg == SEG_CS) && (rpl != cpl)) {
                    return X86EMUL_EXCEPTION;
                }
            }

            d = get_segment_descriptor(ctxt, index, ti);
            if (!d) {
                return X86EMUL_EXCEPTION;
            }

            type = d->type;
            if ((type & 0x18) == 0x10) {
                if (seg != SEG_TR) {
                    return X86EMUL_EXCEPTION;
                }
            } else if ((type & 0x18) == 0x18) {
                if (seg != SEG_LDTR) {
                    return X86EMUL_EXCEPTION;
                }
            } else {
                if (seg != SEG_GDT && seg != SEG_LDT) {
                    return X86EMUL_EXCEPTION;
                }
            }

            if ((type & 0x07) == 0x04) {
                if (seg != SEG_CS) {
                    return X86EMUL_EXCEPTION;
                }
            } else if ((type & 0x07) == 0x00) {
                if (seg != SEG_SS) {
                    return X86EMUL_EXCEPTION;
                }
            } else {
                if ((seg == SEG_CS) || (seg == SEG_SS)) {
                    return X86EMUL_EXCEPTION;
                }
            }

            if ((type & 0x10) == 0) {
                if (seg != SEG_LDT) {
                    return X86EMUL_EXCEPTION;
                }
            }
        }

        d->base = selector_base;
        d->limit = selector_limit;
    }

    if (desc)
        *desc = *d;

    ctxt->segment[seg] = *d;

    return r;
}

int load_segment_descriptor(struct x86_emulate_ctxt *ctxt, u16 selector, int seg, u8 cpl, bool in_task_switch, struct desc_struct *desc) {
    struct desc_struct *d;
    int dpl;
    int rpl = SELECTOR_RPL(selector);
    int ti = SELECTOR_TI(selector);
    int index = SELECTOR_INDEX(selector);
    int error_code = 0;
    int mode;

    if (ctxt->mode == X86EMUL_MODE_REAL || ctxt->mode == X86EMUL_MODE_VM86) {
        if (!selector) {
            d = &ctxt->host_idt;
            dpl = 0;
        } else {
            if (index >=ctxt->ldt.limit)
                return X86EMUL_EXCEPTION(GENERAL_PROTECTION, error_code);

            d = &ctxt->ldt.base;
            dpl = (d->dpl << 8) >> 8;
        }

        if (seg == Vmx_REGS_CS || seg == Vmx_REGS_SS) {
            if ((dpl < rpl) || (dpl < cpl)) {
                return X86EMUL_EXCEPTION(GENERAL_PROTECTION, error_code);
            }
        }

        if (seg == Vmx_REGS_CS) {
            if ((d->type & 0x1F) != 0x0B) {
                return X86EMUL_EXCEPTION(GENERAL_PROTECTION, error_code);
            }
        }

        if (seg == Vmx_REGS_TR) {
            if ((d->type & 0x1F) != 0x09) {
                return X86EMUL_EXCEPTION(GENERAL_PROTECTION, error_code);
            }
        }

        ctxt->segment[seg] = *d;
        if (desc)
            *desc = *d;
        return X86EMUL_CONTINUE;
    }

    if (index >= ctxt->gdt.limit) {
        return X86EMUL_EXCEPTION(GENERAL_PROTECTION, error_code);
    }

    d = &ctxt->gdt.base + index;
    dpl = (d->dpl << 8) >> 8;

    if ((d->type & 0x1F) == 0x00) {
        return X86EMUL_EXCEPTION(GENERAL_PROTECTION, error_code);
    }

    if (seg == Vmx_REGS_CS || seg == Vmx_REGS_SS) {
        if ((d->type & 0x1F) != 0x0B) {
            return X86EMUL_EXCEPTION(GENERAL_PROTECTION, error_code);
        }

        if (dpl < rpl || dpl < cpl) {
            return X86EMUL_EXCEPTION(GENERAL_PROTECTION, error_code);
        }
    }

    if (seg == Vmx_REGS_CS) {
        if ((d->type & 0x1F) != 0x0B) {
            return X86EMUL_EXCEPTION(GENERAL_PROTECTION, error_code);
        }
    }

    if (seg == Vmx_REGS_TR) {
        if ((d->type & 0x1F) != 0x09) {
            return X86EMUL_EXCEPTION(GENERAL_PROTECTION, error_code);
        }
    }

    if ((d->type & 0x1F) >= 0x10) {
        d->type |= 0x04;
    }

    ctxt->segment[seg] = *d;
    if (desc)
        *desc = *d;

    return X86EMUL_CONTINUE;
}
